import numpy as np
from scipy.optimize import least_squares
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
def model(p):
    w=p[0]
    base=p[1]+p[2]*x+p[3]*v+p[4]*v**2+p[5]*np.sin(v)+p[6]*np.sin(x)
    return base+(p[7]+p[8]*x+p[9]*v)*np.cos(w*t)+(p[10]+p[11]*x+p[12]*v)*np.sin(w*t)
rng=np.random.default_rng(1)
best=None
for k in range(300):
    p0=np.concatenate([[rng.uniform(0.2,4)],rng.normal(0,1,12)])
    try:
        r=least_squares(lambda p: model(p)-a,p0,max_nfev=2000)
        n=np.mean(r.fun**2)/np.var(a)
        if best is None or n<best[0]: best=(n,r.x)
    except Exception: pass
p=best[1]; res=a-model(p)
print('best',best[0],np.round(p,3))
